input.content:
'use server'

import { updateTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

const posts: Post[] = []

export async function createPost(formData: FormData): Promise<Post> {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    throw new Error('Title is required')
  }

  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  posts.push(post)

  // Expire the tag immediately so the next read waits for fresh data
  // instead of serving stale cached content (read-your-own-writes).
  updateTag('posts')

  return post
}

export async function getPosts(): Promise<Post[]> {
  return posts
}
